"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Minus, Plus, Trash2, ShoppingBag } from "lucide-react";
import { useCart } from "@/lib/cart/CartContext";
import { Button, ButtonLink } from "@/components/ui/Button";
import { ProductPlaceholder } from "@/components/shop/ProductCard";
import { CouponInput } from "@/components/checkout/CouponInput";
import { OptionalJalaliDatePicker } from "@/components/ui/OptionalJalaliDatePicker";

export function CartView() {
  const { items, updateQuantity, removeItem, clear, totalPrice } = useCart();
  const [address, setAddress] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<"online">("online");
  const [couponCode, setCouponCode] = useState<string | null>(null);
  const [discountAmount, setDiscountAmount] = useState(0);
  const [eventDate, setEventDate] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();
  const finalTotal = totalPrice - discountAmount;

  // A previously-applied coupon's discountAmount was computed against the subtotal at the
  // moment it was applied - if the cart changes afterward, that number would be stale (still
  // shown, no longer accurate), so any cart edit clears it and the customer re-applies against
  // the new subtotal. The final checkout call always re-validates server-side regardless.
  function handleUpdateQuantity(listingId: string, quantity: number) {
    updateQuantity(listingId, quantity);
    setCouponCode(null);
    setDiscountAmount(0);
  }
  function handleRemoveItem(listingId: string) {
    removeItem(listingId);
    setCouponCode(null);
    setDiscountAmount(0);
  }

  async function handleCheckout() {
    setError(null);
    setSubmitting(true);

    try {
      const response = await fetch("/api/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          items: items.map((item) => ({ listingId: item.listingId, quantity: item.quantity })),
          shippingAddress: address,
          paymentMethod,
          couponCode: couponCode ?? undefined,
          eventDate: eventDate ?? undefined,
        }),
      });
      const data = await response.json();

      if (!response.ok) {
        if (data.requiresAuth) {
          router.push(`/auth?redirect=${encodeURIComponent("/cart")}`);
          return;
        }
        setError(data.error ?? "خطایی رخ داد.");
        return;
      }

      clear();
      router.push("/profile");
    } catch {
      setError("ارتباط با سرور برقرار نشد.");
    } finally {
      setSubmitting(false);
    }
  }

  if (items.length === 0) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center gap-3 px-6 py-16 text-center">
        <span className="flex h-16 w-16 items-center justify-center rounded-full bg-rose-50 text-rose-400">
          <ShoppingBag className="h-7 w-7" strokeWidth={1.5} />
        </span>
        <p className="text-sm text-charcoal-muted">سبد خرید شما خالی است.</p>
        <ButtonLink href="/shop" size="md">
          رفتن به فروشگاه
        </ButtonLink>
      </div>
    );
  }

  return (
    <div className="flex flex-1 flex-col gap-5 px-4 py-5 pb-44">
      <ul className="flex flex-col gap-3">
        {items.map((item) => (
          <li
            key={item.listingId}
            className="flex items-center gap-3 rounded-2xl border border-border bg-surface p-3"
          >
            <ProductPlaceholder className="h-16 w-16 shrink-0" />
            <div className="flex-1 space-y-1">
              <p className="line-clamp-1 text-sm font-medium text-charcoal">{item.title}</p>
              <p className="text-sm font-semibold text-charcoal">
                {item.price.toLocaleString("fa-IR")} تومان
              </p>
              {/* docs/design-system.md §6: bordered circle, no filled background - the number
                  sits between the two, unstyled. */}
              <div className="flex items-center gap-2">
                <button
                  onClick={() => handleUpdateQuantity(item.listingId, item.quantity - 1)}
                  className="flex h-7 w-7 items-center justify-center rounded-full border border-border text-charcoal"
                  aria-label="کاهش تعداد"
                >
                  <Minus className="h-3.5 w-3.5" />
                </button>
                <span className="w-5 text-center text-sm">
                  {item.quantity.toLocaleString("fa-IR")}
                </span>
                <button
                  onClick={() => handleUpdateQuantity(item.listingId, item.quantity + 1)}
                  className="flex h-7 w-7 items-center justify-center rounded-full border border-border text-charcoal"
                  aria-label="افزایش تعداد"
                >
                  <Plus className="h-3.5 w-3.5" />
                </button>
              </div>
            </div>
            <button
              onClick={() => handleRemoveItem(item.listingId)}
              className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-rose-50 text-charcoal hover:bg-rose-100"
              aria-label="حذف از سبد"
            >
              <Trash2 className="h-4 w-4" strokeWidth={1.5} />
            </button>
          </li>
        ))}
      </ul>

      <div className="space-y-2">
        <p className="text-sm font-medium text-charcoal">کد تخفیف</p>
        <CouponInput
          subtotal={totalPrice}
          appliedCode={couponCode}
          onApplied={(code, amount) => {
            setCouponCode(code);
            setDiscountAmount(amount);
          }}
          onRemoved={() => {
            setCouponCode(null);
            setDiscountAmount(0);
          }}
        />
      </div>

      <div className="space-y-2">
        <p className="text-sm font-medium text-charcoal">تاریخ جشن (اختیاری)</p>
        <p className="text-xs text-charcoal-muted">
          اگه سفارش شما بین چند فروشنده تقسیم بشه و از مرکز پردازش ویورا عبور کنه، این تاریخ به
          فروشنده‌ها کمک می‌کنه بدونن باید کالا رو تا کِی به مرکز برسونن.
        </p>
        <OptionalJalaliDatePicker label="افزودن تاریخ جشن" value={eventDate} onChange={setEventDate} />
      </div>

      <div className="space-y-2">
        <label htmlFor="address" className="text-sm font-medium text-charcoal">
          آدرس ارسال
        </label>
        <textarea
          id="address"
          value={address}
          onChange={(event) => setAddress(event.target.value)}
          rows={3}
          placeholder="تهران، ..."
          className="w-full rounded-2xl border border-border bg-surface px-4 py-3 text-sm text-charcoal placeholder:text-charcoal-muted/50 focus:border-charcoal focus:outline-none"
        />
      </div>

      <div className="space-y-2">
        <p className="text-sm font-medium text-charcoal">روش پرداخت</p>
        <label className="flex items-center gap-3 rounded-2xl border border-rose-300 bg-rose-50 p-3">
          <input
            type="radio"
            name="payment-method"
            checked={paymentMethod === "online"}
            onChange={() => setPaymentMethod("online")}
            className="h-4 w-4 accent-rose-600"
          />
          <span className="text-sm text-charcoal">پرداخت آنلاین (mock)</span>
        </label>
        <label className="flex items-center gap-3 rounded-2xl border border-border p-3 opacity-50">
          <input type="radio" name="payment-method" disabled className="h-4 w-4" />
          <span className="text-sm text-charcoal-muted">کیف پول ویورا — به‌زودی</span>
        </label>
      </div>

      {/* docs/design-system.md §6: fixed bottom summary bar (the reference's own Checkout bar) -
          sits just above BottomNav (reserved 80px, MainLayout's own pb-20) rather than the page's
          true bottom, so the two never overlap. pb-44 on the scroll container above keeps the
          payment-method radios clear of this bar's own height. */}
      <div className="fixed inset-x-0 bottom-20 z-30 mx-auto w-full max-w-md border-t border-border bg-surface/95 px-4 py-3 backdrop-blur">
        <div className="space-y-1 text-sm">
          <div className="flex items-center justify-between text-charcoal-muted">
            <span>جمع سبد</span>
            <span>{totalPrice.toLocaleString("fa-IR")} تومان</span>
          </div>
          {discountAmount > 0 ? (
            <div className="flex items-center justify-between text-charcoal-muted">
              <span>تخفیف</span>
              <span>-{discountAmount.toLocaleString("fa-IR")} تومان</span>
            </div>
          ) : null}
          <div className="flex items-center justify-between pt-1">
            <span className="font-medium text-charcoal">جمع کل</span>
            <span className="text-lg font-bold text-charcoal">
              {finalTotal.toLocaleString("fa-IR")} تومان
            </span>
          </div>
        </div>

        {error ? <p className="pt-1 text-center text-sm text-error-500">{error}</p> : null}

        <Button
          size="lg"
          className="mt-3 w-full"
          disabled={submitting || address.trim().length < 5}
          onClick={handleCheckout}
        >
          {submitting ? "در حال ثبت سفارش…" : "تکمیل خرید"}
        </Button>
      </div>
    </div>
  );
}
